values
  ('7f7772c0-3ac8-4f54-af09-3572cbb086d3', 'd6e7f8a9-0b1c-4d22-9e12-2f3a4b5c6d32', null, 'topic'::public.curated_course_node_type, 'First Amendment Foundations', 'Media law begins with the constitutional structure that protects, limits, and shapes American journalism. Students learn the core principles of speech and press freedom and why those principles are contested in real reporting situations.', 0),
