update public.learning_paths
set
  title = 'Media Law',
  goal = 'Media Law',
  summary = 'A core undergraduate journalism course in First Amendment principles, defamation, privacy, reporter privilege, access to information, copyright, broadcast regulation, digital publishing, student press rights, and emerging media law. The course develops legal literacy for reporting and editing decisions; it is educational and does not provide legal advice.',
  data = $mlawjson${"slug": "media-law", "title": "Media Law", "description": "A core undergraduate journalism course in First Amendment principles, defamation, privacy, reporter privilege, access to information, copyright, broadcast regulation, digital publishing, student press rights, and emerging media law. The course develops legal literacy for reporting and editing decisions; it is educational and does not provide legal advice.", "topics": [{"id": "7f7772c0-3ac8-4f54-af09-3572cbb086d3", "type": "topic", "title": "First Amendment Foundations", "description": "Media law begins with the constitutional structure that protects, limits, and shapes American journalism. Students learn the core principles of speech and press freedom and why those principles are contested in real reporting situations.", "children": [{"id": "fe6cb4df-3bb0-402f-ab27-c1a1042c3bff", "type": "subtopic", "title": "Speech, press, and democratic accountability", "children": [{"id": "093292b1-b563-4167-a1b0-053fbc6017a3", "type": "concept", "title": "Marketplace of ideas"}, {"id": "afd384be-c0bc-4d28-a39a-d6ea5262d1df", "type": "concept", "title": "Watchdog role"}, {"id": "1b66f8ba-f68e-4ce8-964d-14931ce1ab5c", "type": "concept", "title": "Political speech"}, {"id": "657eca31-dba6-42e3-b0ac-2c3d7c3ccc97", "type": "concept", "title": "Public concern"}], "description": "Students learn why press freedom is tied to public oversight, dissent, and informed self-government."}, {"id": "aa65a2a2-7047-471f-aec5-8cde2ea26214", "type": "subtopic", "title": "Levels of protection", "children": [{"id": "3e1798de-732f-44c0-9459-1c37f3cd2564", "type": "concept", "title": "Political speech"}, {"id": "4261f520-e24b-43e4-9687-f79b66907a5c", "type": "concept", "title": "Commercial speech"}, {"id": "d6543910-9e91-4491-a6ba-ac4b9214e398", "type": "concept", "title": "Obscenity"}, {"id": "1d97804c-3a8e-4808-a771-7b1c551754dc", "type": "concept", "title": "True threats"}], "description": "The point is to distinguish highly protected speech from categories that receive less or no protection."}, {"id": "c7222ea3-7b45-4d60-a075-c5c5b6e50aa3", "type": "subtopic", "title": "State action and government limits", "children": [{"id": "9f6459c8-4269-4b91-b4b6-a435d926cd48", "type": "concept", "title": "Government actors"}, {"id": "bc770b61-1287-4b44-b729-f740df31bc9b", "type": "concept", "title": "Private publishers"}, {"id": "8d6e8e60-88d5-4dfa-9f63-a2e85f94b942", "type": "concept", "title": "Public forums"}, {"id": "6d9d5fb3-ca72-4c22-98cc-0248236534da", "type": "concept", "title": "Time, place, and manner rules"}], "description": "Students learn when the First Amendment applies and when private platforms, employers, or schools raise different legal questions."}]}, {"id": "6dbefd30-2a68-4f37-94e7-8f2753aeef7a", "type": "topic", "title": "Prior Restraint and Publication Injunctions", "description": "Prior restraint is one of the most serious threats to publication. Students learn why courts rarely stop publication in advance and what journalists should do when threatened with an injunction.", "children": [{"id": "0dea2b2a-d518-4560-a18a-0aad3e69db6e", "type": "subtopic", "title": "The presumption against prior restraint", "children": [{"id": "7bc72689-c923-45a8-b0e2-b35bd242741c", "type": "concept", "title": "Near v. Minnesota"}, {"id": "4042bab5-b25d-48c0-af71-bc87c70124b6", "type": "concept", "title": "Pentagon Papers"}, {"id": "4d588c46-19bc-4ef3-b394-1627a6afb71d", "type": "concept", "title": "Heavy burden"}, {"id": "7599321d-f45b-4a22-b619-d53987c2eaf1", "type": "concept", "title": "National security claims"}], "description": "Students study the legal suspicion toward government efforts to block speech before it reaches the public."}, {"id": "4c9b49f5-5fad-495f-821e-4b6e4beca1d3", "type": "subtopic", "title": "Emergency injunction practice", "children": [{"id": "d24bd229-b118-4879-a11c-1f0d9b3ff30e", "type": "concept", "title": "Notice to counsel"}, {"id": "dce8d0fe-65dc-498b-a6b7-f8d8f501f402", "type": "concept", "title": "Evidence preservation"}, {"id": "2da18291-ffdc-427a-a9eb-69b60520f524", "type": "concept", "title": "Editorial review"}, {"id": "1ebce685-5d49-46ae-a09b-58d9ffae4e2c", "type": "concept", "title": "Publication timing"}], "description": "Students learn the newsroom workflow when a source, corporation, court, or government actor seeks to halt publication."}, {"id": "f5b742f6-db67-4f5a-bb1b-85ed96471fd7", "type": "subtopic", "title": "Leaks and confidential documents", "children": [{"id": "e8f7953d-b47b-4502-bd4c-d7382277f64b", "type": "concept", "title": "Lawful receipt"}, {"id": "605cdc42-67c9-437b-8e54-148a8583d35d", "type": "concept", "title": "Source conduct"}, {"id": "a9813fc7-783b-4a86-8e03-1f551ab5fdc5", "type": "concept", "title": "Trade secrets"}, {"id": "953d9637-9faa-41c2-a492-b745d8881b30", "type": "concept", "title": "Classified information"}], "description": "The goal is to understand legal and ethical risk when publishing truthful information obtained from sources."}]}, {"id": "cdb42063-172e-4c3a-b2f1-5cbae85bfbc8", "type": "topic", "title": "Libel and Defamation", "description": "Defamation law is central to journalism because it governs false statements that harm reputation. Students learn how to report aggressively while reducing avoidable legal risk.", "children": [{"id": "bbd0ff83-f021-4985-9352-793f4d0e3077", "type": "subtopic", "title": "Elements of a defamation claim", "children": [{"id": "103582a0-0729-4c3c-b2ba-41c44bbfa21d", "type": "concept", "title": "Defamatory statement"}, {"id": "5b3256e3-fba8-49d8-8f0e-bad1f900990e", "type": "concept", "title": "Identification"}, {"id": "f51bd59e-8528-4b55-9c62-9fdd48ca9bd6", "type": "concept", "title": "Publication"}, {"id": "54876148-379f-438d-ac6b-f506574f926f", "type": "concept", "title": "Falsity"}, {"id": "700f953e-c32f-45a4-9571-2389808b91ab", "type": "concept", "title": "Fault"}, {"id": "c7a37fdf-4015-4953-a0d4-edc81e0569d9", "type": "concept", "title": "Damages"}], "description": "Students learn the building blocks plaintiffs usually must prove."}, {"id": "9b01dd78-a17e-4613-97de-a5a01e1fb283", "type": "subtopic", "title": "Public officials, public figures, and actual malice", "children": [{"id": "cf86fe99-6804-458c-9843-184c9125fcb2", "type": "concept", "title": "New York Times v. Sullivan"}, {"id": "52a06a4f-7cb9-4208-bd0b-a23f13dc29b2", "type": "concept", "title": "Actual malice"}, {"id": "3cc2784c-e45c-43a2-8140-0249b0999498", "type": "concept", "title": "Limited-purpose public figures"}, {"id": "872ef547-832b-472b-b64b-e296ac6f8c88", "type": "concept", "title": "Negligence standard"}], "description": "Students study the heightened protection for reporting on public power and public controversy."}, {"id": "9d744ad2-d8f0-42cd-ba0e-3c10f04a6fda", "type": "subtopic", "title": "Defenses and risk reduction", "children": [{"id": "14ec1976-ee3a-45e7-be80-efcbd4449839", "type": "concept", "title": "Truth"}, {"id": "654711fe-e8d8-435a-83d3-e46187a29ba0", "type": "concept", "title": "Opinion"}, {"id": "28b15c1d-f809-41b8-af6f-c59c97bdb2fe", "type": "concept", "title": "Fair report privilege"}, {"id": "729fbb37-c6f9-40fe-a462-a083421669b3", "type": "concept", "title": "Neutral reportage"}, {"id": "3126a234-298a-43f2-9580-ff6362d56e02", "type": "concept", "title": "Right of reply"}], "description": "The point is to build reporting habits that make stories more accurate and more defensible."}]}, {"id": "7bd14968-63e0-47e0-a409-c1159c726938", "type": "topic", "title": "Privacy Law and Public Interest", "description": "Privacy law asks journalists to balance news value, dignity, consent, and harm. Students learn the four major privacy torts and how public interest changes the analysis.", "children": [{"id": "6d124823-e5ba-44a9-a0cf-bbefc322594a", "type": "subtopic", "title": "Intrusion and private spaces", "children": [{"id": "f40ab640-90eb-4b39-921f-8e436dcef90b", "type": "concept", "title": "Reasonable expectation of privacy"}, {"id": "22705d25-c703-48d2-a85b-5a2bd3ac27ec", "type": "concept", "title": "Trespass"}, {"id": "55abb236-2059-46e2-b43c-6e04dda3479e", "type": "concept", "title": "Hidden recording"}, {"id": "cb5f7ee1-18b7-4100-a51f-656374258b01", "type": "concept", "title": "Harassment"}], "description": "Students learn when newsgathering itself can create liability even before publication."}, {"id": "dd2da9c6-1898-4a36-b114-b8e1c5ef4338", "type": "subtopic", "title": "Publication of private facts", "children": [{"id": "888f4b11-b941-45ad-b47d-3319218d6f0a", "type": "concept", "title": "Newsworthiness"}, {"id": "eac39d66-525f-4496-a697-350d12802d8c", "type": "concept", "title": "Medical information"}, {"id": "0ea03bc7-3b17-4581-bdc0-b87e3d7a9817", "type": "concept", "title": "Minors"}, {"id": "6c164fa0-a04c-4a15-a1c9-e551a270e891", "type": "concept", "title": "Victims and families"}], "description": "Students practice deciding when truthful private information is newsworthy enough to publish."}, {"id": "70c3bf85-7150-4d4c-8523-d64422812792", "type": "subtopic", "title": "False light and appropriation", "children": [{"id": "922a29d9-4607-4bdc-9e60-a2bd2d8d01be", "type": "concept", "title": "Misleading context"}, {"id": "b9852070-f170-415d-9129-e66876a2d12d", "type": "concept", "title": "Photo selection"}, {"id": "91acad2a-93d1-48e6-8057-6aed3d57aabb", "type": "concept", "title": "Name/image likeness"}, {"id": "1ed03fd7-23ce-41a0-a71a-64e9d94e0eb0", "type": "concept", "title": "Consent"}], "description": "The goal is to avoid misleading portrayals and unauthorized commercial use of identity."}]}, {"id": "808a228a-1334-4661-8a60-c4c24cc280cd", "type": "topic", "title": "Newsgathering Law and Reporter Conduct", "description": "Legal risk often starts in the reporting process. This section teaches students how access, recording, deception, trespass, and safety decisions affect lawful journalism.", "children": [{"id": "da0ccd93-10b7-42f4-83a2-d6dab4ae4bcb", "type": "subtopic", "title": "Recording, consent, and surveillance", "children": [{"id": "83097f0e-16d2-4ce8-8dc8-0f00ee8d9aea", "type": "concept", "title": "One-party consent"}, {"id": "6fe0171c-b499-4ab3-ac9b-61087eb292df", "type": "concept", "title": "All-party consent"}, {"id": "d8d3055e-8db1-47a5-a6be-76eb93cc772b", "type": "concept", "title": "Public recording"}, {"id": "8cd27575-fd61-477d-bfd9-ad56138d480f", "type": "concept", "title": "Private conversations"}], "description": "Students learn how audio, video, phone, and digital recording rules vary and why consent matters."}, {"id": "cd64f755-3712-4c23-b199-c7fe5cfbc012", "type": "subtopic", "title": "Trespass, misrepresentation, and undercover work", "children": [{"id": "6a6144fb-cad9-4ade-98a3-ad70e3fa6b76", "type": "concept", "title": "Private property"}, {"id": "3c12349f-625c-4caa-8304-3174e3343481", "type": "concept", "title": "Press credentials"}, {"id": "af6c8b12-33d7-4378-b8b6-3439d86c10a0", "type": "concept", "title": "Undercover reporting"}, {"id": "3cce4b35-2243-4e1d-add3-c8daca2224b4", "type": "concept", "title": "Terms of entry"}], "description": "Students examine the difference between aggressive reporting and unlawful conduct."}, {"id": "f77e2820-5afc-477a-b64e-8190133b9376", "type": "subtopic", "title": "Protests, crime scenes, and police encounters", "children": [{"id": "3901399d-2278-4585-bbf2-6b74cdbc9209", "type": "concept", "title": "Police orders"}, {"id": "ea0c6eef-7339-4e4e-93ad-d9d4defcebdf", "type": "concept", "title": "Arrest risk"}, {"id": "2453c4d8-6f11-4650-9ba0-6202e529b69d", "type": "concept", "title": "Credentialing"}, {"id": "887ec2d6-5d50-448d-aea4-da1a87622603", "type": "concept", "title": "Evidence handling"}], "description": "The point is to know the reporter's rights and practical limits in volatile field situations."}]}, {"id": "24a242d7-aa93-479b-8db0-be63e277aed2", "type": "topic", "title": "Reporter Privilege, Confidential Sources, and Shield Laws", "description": "Source protection is essential but not absolute. Students learn how subpoenas, shield laws, confidentiality promises, and newsroom policies shape source relationships.", "children": [{"id": "7dc4adde-36dc-4a4c-b7fb-05775333793b", "type": "subtopic", "title": "Confidentiality promises", "children": [{"id": "e5de8a5a-3300-4ff9-b70a-f47fd3a94da9", "type": "concept", "title": "On background"}, {"id": "c746bfbd-c24a-4600-a0bc-c247b16cc1fc", "type": "concept", "title": "Off the record"}, {"id": "6d70f746-5cdb-4e2b-a528-3f17dd205d85", "type": "concept", "title": "Deep background"}, {"id": "134e9c84-1aec-4ca1-b852-c113de7a394a", "type": "concept", "title": "Anonymity policies"}], "description": "Students learn to make source promises carefully and understand who can authorize them."}, {"id": "753e2f80-e459-4f66-b843-7d04d6905cf6", "type": "subtopic", "title": "Subpoenas and compelled testimony", "children": [{"id": "d23e4cd3-16bc-4a6d-a2fc-271894f88bd4", "type": "concept", "title": "Branzburg v. Hayes"}, {"id": "b7093e0a-6306-4c5e-afbb-f3df937574b0", "type": "concept", "title": "Civil subpoenas"}, {"id": "cbc10df0-d19b-4355-86f4-47d0cea277d0", "type": "concept", "title": "Criminal subpoenas"}, {"id": "7dad9529-2b72-47f2-85fa-3574e926fcd2", "type": "concept", "title": "Contempt"}], "description": "Students examine when reporters may be ordered to identify sources or turn over materials."}, {"id": "b4a3bf2f-8858-4653-b5b3-e8ecf755b026", "type": "subtopic", "title": "State shield laws and practical response", "children": [{"id": "b105b634-f19b-4c67-811a-cd4cb0932708", "type": "concept", "title": "Qualified privilege"}, {"id": "85e0c7e7-c853-43de-8a53-f8cf86a3e25f", "type": "concept", "title": "Absolute privilege"}, {"id": "37ce1375-2d6f-472d-8832-4716802b8576", "type": "concept", "title": "Jurisdiction differences"}, {"id": "fe99b09f-2c70-4a3d-94f7-c27ca35826dc", "type": "concept", "title": "Legal escalation"}], "description": "The goal is to understand why protections vary and how newsrooms respond."}]}, {"id": "0bf5292b-5cca-4e3f-8229-0dff0a058a83", "type": "topic", "title": "Access to Courts, Records, and Public Meetings", "description": "Accountability reporting depends on access. Students learn the legal foundations and practical methods for entering courts, using records, and covering public bodies.", "children": [{"id": "96fe8e29-e8a6-43c4-8763-ae191b7659e9", "type": "subtopic", "title": "Court access", "children": [{"id": "c496e191-39a1-4d7c-86f7-4f341537aab9", "type": "concept", "title": "Open courts"}, {"id": "7a9969fe-90d1-4c63-8285-1f600f73c511", "type": "concept", "title": "Sealing orders"}, {"id": "2749adb0-eedb-4273-addc-e17cce1948ec", "type": "concept", "title": "Gag orders"}, {"id": "18b346fb-85cc-4beb-8495-49e6831f643a", "type": "concept", "title": "Cameras in court"}], "description": "Students learn the public's presumptive right to attend proceedings and inspect some court records."}, {"id": "d225e830-5161-4e09-9049-4ee694f2a6c8", "type": "subtopic", "title": "Open meetings", "children": [{"id": "6b6bb483-62d9-4bc7-9d6c-fb8de5984033", "type": "concept", "title": "Notice"}, {"id": "eeb8f81e-e7af-4bfe-b804-50ed1ce73220", "type": "concept", "title": "Agendas"}, {"id": "f7574499-8d54-4c6a-9db4-682e8d02e69f", "type": "concept", "title": "Executive sessions"}, {"id": "ce9820b1-d9c6-4e89-ac20-6f0b6a424fac", "type": "concept", "title": "Meeting minutes"}], "description": "Students learn how state sunshine laws support coverage of school boards, councils, commissions, and public agencies."}, {"id": "662c610f-76e9-452f-8691-c1928dfaac56", "type": "subtopic", "title": "Access strategy", "children": [{"id": "fd1e5503-155d-4e9e-907e-d51295dc474b", "type": "concept", "title": "Polite assertion of rights"}, {"id": "018d2a4e-bf03-47f5-b0d2-d0d0b303de9c", "type": "concept", "title": "Documenting denials"}, {"id": "b6d41353-853b-45ea-8f0c-b3d89028c442", "type": "concept", "title": "Appeal pathways"}, {"id": "9019871c-9ac1-4869-bc48-5be180ae9b4e", "type": "concept", "title": "Legal help resources"}], "description": "The point is to turn legal rights into usable reporting routines."}]}, {"id": "98002ec9-f785-493b-a89b-9081d33e5ad6", "type": "topic", "title": "FOIA and Public Records Practice", "description": "Public records law is both a legal subject and a reporting skill. Students learn how to request, negotiate, appeal, and use records ethically.", "children": [{"id": "b72d8a73-6602-4037-adb2-f5fb5f9e5c66", "type": "subtopic", "title": "Federal FOIA basics", "children": [{"id": "af90e51f-7bc0-4b16-a4b7-13497b3f5550", "type": "concept", "title": "Agency records"}, {"id": "4f60d0c8-c07f-4d2b-b38e-7e28132c6eb2", "type": "concept", "title": "Exemptions"}, {"id": "e14ad17e-ec8b-4e36-bd19-ca49b1c2fa7a", "type": "concept", "title": "Fee categories"}, {"id": "bc117f69-b25d-443c-b6f3-65da2410eae6", "type": "concept", "title": "Administrative appeals"}], "description": "Students learn the structure of federal requests, exemptions, timeframes, and appeals."}, {"id": "d4ed31fc-6b62-45b2-80a0-775bfe2912ce", "type": "subtopic", "title": "State and local records", "children": [{"id": "1313cd6c-adf3-4cb4-bd3e-7800a47719f4", "type": "concept", "title": "Police records"}, {"id": "5b0367c8-e85d-4403-9e36-1cdc4764d07b", "type": "concept", "title": "Budgets"}, {"id": "b9f32e0d-4417-4082-96f2-c4ffe5c8e7ea", "type": "concept", "title": "Contracts"}, {"id": "85a0a59e-be72-4a18-8b5c-a289cd459b26", "type": "concept", "title": "Inspection reports"}], "description": "Students learn why most daily accountability reporting uses state public-records laws."}, {"id": "e9753092-8471-4a38-bf10-85772e7208e7", "type": "subtopic", "title": "Records workflow", "children": [{"id": "bb1c4d1f-3d5b-4fe6-aac3-e04501aef342", "type": "concept", "title": "Request wording"}, {"id": "a942a4b1-a720-487f-9a05-7d38799967fe", "type": "concept", "title": "Tracking logs"}, {"id": "5a3b46fa-9a6f-40ea-b861-6cef78d6a48b", "type": "concept", "title": "Negotiation"}, {"id": "48b802a8-abb3-4bec-b008-80bb7c05acf6", "type": "concept", "title": "Document analysis"}], "description": "The goal is to make requests narrow, trackable, and useful for stories."}]}, {"id": "71d028f9-fdc7-4f5e-ac60-64b368467ac2", "type": "topic", "title": "Copyright, Licensing, and Fair Use", "description": "Journalists use, quote, embed, remix, and publish copyrighted material constantly. Students learn how copyright protects expression and when fair use supports reporting.", "children": [{"id": "edc11aff-70e2-4a86-bde2-107675931d2b", "type": "subtopic", "title": "Copyright basics", "children": [{"id": "005cc18e-c11c-4c17-8132-e69e4e39621d", "type": "concept", "title": "Original expression"}, {"id": "0b2aa4a5-a722-4992-9f3a-dbaab1954bf7", "type": "concept", "title": "Ideas vs. expression"}, {"id": "7215885b-0c35-46fa-a922-bb3154bc5606", "type": "concept", "title": "Facts"}, {"id": "ac774df1-8024-49a3-9699-2cf6fffd859c", "type": "concept", "title": "Public domain"}], "description": "Students learn what copyright protects and what it does not."}, {"id": "4e477109-e419-4971-af2d-436abb7fc414", "type": "subtopic", "title": "Fair use analysis", "children": [{"id": "f846ada6-153b-4189-be1b-53dacfaf691c", "type": "concept", "title": "Purpose"}, {"id": "b1a1d39e-5d49-4565-ba72-cf0f124b0e75", "type": "concept", "title": "Nature"}, {"id": "e23d09aa-dd1a-4599-896f-dbe98fd30eae", "type": "concept", "title": "Amount"}, {"id": "60b35349-bda2-4082-acde-4749b95cc555", "type": "concept", "title": "Market effect"}], "description": "Students practice applying the four-factor test in journalism contexts."}, {"id": "618e0dd0-97ed-4a48-8259-cfadd71b3dab", "type": "subtopic", "title": "Permissions and newsroom media use", "children": [{"id": "4c4b4816-fab7-46e7-a3ce-316c18e6b18e", "type": "concept", "title": "Licenses"}, {"id": "4eff5cb0-c2fd-4da8-81fe-cac3c2f1cf00", "type": "concept", "title": "Creative Commons"}, {"id": "f1e4a5cb-13a7-4972-9153-c7c6f508f99d", "type": "concept", "title": "Embeds"}, {"id": "d1f137ab-ec76-4fca-83b1-fec569d296ff", "type": "concept", "title": "Takedown requests"}], "description": "The point is to manage images, music, video, screenshots, and user-generated content responsibly."}]}, {"id": "424643bc-6d99-4017-a230-70f25a8f39f1", "type": "topic", "title": "Commercial Speech, Advertising, and Sponsored Content", "description": "Journalism students need to understand the legal boundary between editorial work and commercial persuasion. This section covers advertising, endorsements, native advertising, and consumer-protection concerns.", "children": [{"id": "45f65e89-5da9-4d43-bfd3-7d8c757c2a14", "type": "subtopic", "title": "Commercial speech doctrine", "children": [{"id": "aed96bae-b71e-41fa-a3e1-92a7ca7b01aa", "type": "concept", "title": "Central Hudson test"}, {"id": "9c27bae0-0182-4323-9c43-eb8f4dd30290", "type": "concept", "title": "False advertising"}, {"id": "c56a8843-fe7b-43d5-9087-26444f8cbe78", "type": "concept", "title": "Regulated industries"}, {"id": "f01a9bdb-72d2-482a-ae74-2ba6aaf773d3", "type": "concept", "title": "Disclosures"}], "description": "Students learn why advertising receives protection but less protection than core political speech."}, {"id": "4d69e767-4a9f-4baa-99d7-224ea6bcbe32", "type": "subtopic", "title": "Native advertising and sponsorship", "children": [{"id": "ae99c142-1023-4466-ba37-3d04521d81e0", "type": "concept", "title": "Sponsored labels"}, {"id": "3e589d50-44a7-4561-8607-dd0f2b60448c", "type": "concept", "title": "Influencer disclosure"}, {"id": "6f094bf5-c8f2-4250-8f30-06bf1089aab4", "type": "concept", "title": "Brand studios"}, {"id": "c491b246-d4c9-4791-b6fd-d0646ebf218b", "type": "concept", "title": "Reader confusion"}], "description": "Students examine the legal and ethical need for clear separation between editorial and paid content."}, {"id": "4497ef2f-4788-4c95-a9c3-7e2aba643664", "type": "subtopic", "title": "Newsroom independence", "children": [{"id": "158dbc83-b6b0-462d-a450-e91ba899e736", "type": "concept", "title": "Ad/editorial wall"}, {"id": "eda7e505-43b4-4aae-9334-cc982299a6e7", "type": "concept", "title": "Conflicts of interest"}, {"id": "3ebb2b09-d1b7-46d0-bbc0-cfa49ed65b9d", "type": "concept", "title": "Product claims"}, {"id": "fd2061b9-d49c-46ed-90e0-8f3f5a6fe598", "type": "concept", "title": "Corrections"}], "description": "The goal is to connect law, ethics, and trust in revenue-supported media."}]}, {"id": "40b2fe79-bc41-42eb-a6e9-00eef19c2ce4", "type": "topic", "title": "Broadcast Regulation and FCC Rules", "description": "Broadcast journalism operates under a distinctive regulatory history. Students learn how licensing, indecency, political broadcasting, and public-interest obligations differ from print and web publication.", "children": [{"id": "2de83645-6820-4a18-8cc9-eb21f5724474", "type": "subtopic", "title": "Spectrum licensing and public interest", "children": [{"id": "52328f6f-bba7-4a54-b4a5-20aa8cd4375d", "type": "concept", "title": "Scarcity rationale"}, {"id": "c0365d2a-f6a8-4187-af67-688ff9aed17d", "type": "concept", "title": "Licenses"}, {"id": "f4c75aa8-69f9-4bc3-a1e5-7eae25274924", "type": "concept", "title": "Public file"}, {"id": "564ab4da-017b-466d-b1e8-ff67ddf8d259", "type": "concept", "title": "Localism"}], "description": "Students learn why broadcast outlets are regulated differently from newspapers and websites."}, {"id": "00373526-93df-4ee2-ba48-0bd4534106b1", "type": "subtopic", "title": "Content regulation", "children": [{"id": "183ed767-d778-4684-82c4-96f4440d9b24", "type": "concept", "title": "Indecency"}, {"id": "b8c638fd-d731-4244-9f35-addd5ef6f31e", "type": "concept", "title": "Safe harbor"}, {"id": "ec21abef-fb85-40b2-aee3-019b93e9895b", "type": "concept", "title": "Hoaxes"}, {"id": "c6988396-23d8-4f38-a46e-ec57091a42d4", "type": "concept", "title": "Emergency alerts"}], "description": "Students examine the legal limits around indecency, obscenity, hoaxes, and emergency information."}, {"id": "bcb6da82-84b2-4c06-ab99-6ddbce343e9c", "type": "subtopic", "title": "Political broadcasting", "children": [{"id": "7fa4c4d7-f645-4270-91f4-bb343c102d12", "type": "concept", "title": "Equal opportunities"}, {"id": "78e41fa2-7e75-4405-ba30-a57cd11f1ad3", "type": "concept", "title": "Lowest unit rate"}, {"id": "19ff9bab-82d4-4382-811a-b016d8aa1d9f", "type": "concept", "title": "Sponsorship identification"}, {"id": "b154101b-de4d-4af7-a4a1-451de1d9e1b6", "type": "concept", "title": "Issue ads"}], "description": "The goal is to understand election-season rules affecting candidates and stations."}]}, {"id": "f65a7f0b-2682-4cf9-ae46-4dcb67ae1ab3", "type": "topic", "title": "Online, Platform, and Social Media Law", "description": "Digital publishing changes jurisdiction, distribution, moderation, and liability questions. Students learn the law that shapes online journalism and social media practice.", "children": [{"id": "db42e1f3-23bd-4ce4-8688-fd2db87499ad", "type": "subtopic", "title": "Platform liability and Section 230", "children": [{"id": "0936139d-bd99-4870-b58a-41513bb66405", "type": "concept", "title": "User-generated content"}, {"id": "552e1859-2831-4aba-91f8-31c9eac30038", "type": "concept", "title": "Moderation"}, {"id": "1fc68a31-2301-469a-964d-271d31c185c4", "type": "concept", "title": "Publisher vs. platform"}, {"id": "821fb249-c6ba-487d-9c50-e16463703c7a", "type": "concept", "title": "Limits of immunity"}], "description": "Students learn the difference between publisher liability and platform immunity for user content."}, {"id": "ae87b5b8-6e2b-4cf9-bf6c-6503b4ce921f", "type": "subtopic", "title": "Online defamation and jurisdiction", "children": [{"id": "fe08ee15-e586-48d4-8b97-6632c4aef864", "type": "concept", "title": "Single publication rule"}, {"id": "0ff2d4c9-3d4e-49e8-819e-260edb0c1ab9", "type": "concept", "title": "Retweets and shares"}, {"id": "4e62dce1-f71f-408b-8be5-a12d76da932f", "type": "concept", "title": "Jurisdiction"}, {"id": "2437de4e-80b2-4c5d-aafb-2bcbc351ea3a", "type": "concept", "title": "Anonymous commenters"}], "description": "Students examine how publication online affects audience reach, republication, and lawsuit venue."}, {"id": "9ca9f6c6-11ad-4a39-9fe5-bba4a4d74675", "type": "subtopic", "title": "Digital takedowns and corrections", "children": [{"id": "a9f1cd93-4c8a-4a20-bd93-2b8d31365d04", "type": "concept", "title": "Right-to-be-forgotten debates"}, {"id": "b287aa3f-7e7a-42d3-b814-b57f75cf4563", "type": "concept", "title": "Unpublishing"}, {"id": "31b1d143-8ae9-45a0-a614-adc156c9b5da", "type": "concept", "title": "Correction notes"}, {"id": "a1f81206-78ea-4028-9130-e9cb3ad8aec1", "type": "concept", "title": "Archive integrity"}], "description": "The point is to manage complaints, updates, removals, and search visibility responsibly."}]}, {"id": "9f77594d-0bbc-4039-8b1a-16d16265678e", "type": "topic", "title": "Student Press, Campus Speech, and Educational Settings", "description": "Because this is an undergraduate course, students need a dedicated look at campus press law. This section covers the unique rights and constraints of student journalists.", "children": [{"id": "ba80a919-6240-4354-a748-fa7d8c61fb0a", "type": "subtopic", "title": "Student press rights", "children": [{"id": "f8d004f2-45c9-406f-8acc-a379a308cae9", "type": "concept", "title": "Hazelwood"}, {"id": "0e03e6fb-ec19-43c3-831c-f9a5767eb67d", "type": "concept", "title": "College press"}, {"id": "e804a28a-cb77-4483-8071-f39f4e4cb51e", "type": "concept", "title": "Forum status"}, {"id": "05e3551a-dc07-4e48-8b61-029cf9fc5e5f", "type": "concept", "title": "New Voices laws"}], "description": "Students compare student media protection in public schools, colleges, and private institutions."}, {"id": "3be3ad00-a6ad-4140-b070-04c4caa8b5fd", "type": "subtopic", "title": "Campus records and safety reporting", "children": [{"id": "9f427042-a4da-4f98-892c-5f421c6f9fd3", "type": "concept", "title": "Clery Act"}, {"id": "eef43edc-2e9b-4718-b6e9-6c4a27b59292", "type": "concept", "title": "FERPA"}, {"id": "dbefc9b6-feec-41c3-92bf-72809b9994b4", "type": "concept", "title": "Campus police"}, {"id": "925ffc07-71c0-4137-bae5-384b51c8f07e", "type": "concept", "title": "Disciplinary records"}], "description": "Students learn legal tools and limits for reporting on universities."}, {"id": "d0ebd616-0c95-4b49-839f-689a92f7ed78", "type": "subtopic", "title": "Editorial independence on campus", "children": [{"id": "f2d0273a-aa53-4fd5-84d0-9cb9136c2e77", "type": "concept", "title": "Prior review"}, {"id": "8b5bbafa-3549-46b7-8b86-b986d95d9083", "type": "concept", "title": "Student government pressure"}, {"id": "f463ffd4-94f3-4852-b9ce-0d6e977d3606", "type": "concept", "title": "Funding control"}, {"id": "2f1901f6-0c9e-44ca-b4ee-830d4a05cc87", "type": "concept", "title": "Legal support"}], "description": "The goal is to prepare students for censorship, adviser pressure, funding threats, and administrative pushback."}]}, {"id": "8c926c47-d7d4-4166-b7e9-4ddf07a3042e", "type": "topic", "title": "Emerging Media Law, AI, Deepfakes, and Newsroom Risk Review", "description": "World-class media law training must prepare students for legal questions that are still developing. Students learn how to reason through unsettled issues without pretending the law is static.", "children": [{"id": "4efad2e4-0d40-42a0-adaa-4d68cc18ab19", "type": "subtopic", "title": "AI-generated and synthetic media", "children": [{"id": "68725854-e9d4-4bf8-bb14-f4d029a894d7", "type": "concept", "title": "Defamation"}, {"id": "6869f39e-0633-49f4-9403-c8157b2db7b0", "type": "concept", "title": "False light"}, {"id": "1f0000d6-769f-4056-bed0-0da837314600", "type": "concept", "title": "Copyright inputs"}, {"id": "8db3c2a3-1af8-4248-922e-e88e8dcd061e", "type": "concept", "title": "Labeling"}], "description": "Students examine legal risks around deepfakes, synthetic voice, generated images, and disclosure."}, {"id": "85ea553f-faa2-4e98-a52e-1389e8461f33", "type": "subtopic", "title": "Data, privacy, and security", "children": [{"id": "05c0d296-9343-45c7-90ac-f4b0239d192f", "type": "concept", "title": "Data scraping"}, {"id": "ed440965-30a5-4471-94ec-06365c39546f", "type": "concept", "title": "Doxxing"}, {"id": "101f47f6-33c6-4488-b0f1-9ca12b686feb", "type": "concept", "title": "Source security"}, {"id": "bb0e0b2c-003c-4ef5-9df3-0dbaed37e4a0", "type": "concept", "title": "Sensitive datasets"}], "description": "Students learn how digital reporting creates privacy and security obligations."}, {"id": "56306b01-5948-451d-8bb4-e52a241fbe23", "type": "subtopic", "title": "Pre-publication review", "children": [{"id": "a94313cb-1527-4029-817c-81113d7218c8", "type": "concept", "title": "Red flags"}, {"id": "95da6b56-9cec-4907-a6bd-5a5ffa280c32", "type": "concept", "title": "Documentation"}, {"id": "e5ce33b3-c62e-470f-bf48-018185851edd", "type": "concept", "title": "Counsel review"}, {"id": "034cd180-91c9-4c04-a78a-39be62f1259d", "type": "concept", "title": "Post-publication response"}], "description": "The goal is to leave students with a practical legal-risk checklist for ambitious stories."}]}], "dbBacked": true}$mlawjson$::jsonb,
